    {
      "n": 5,
      "id": "contabilidad.configurar-informe-contable#5",
      "texto": "Defina la estructura que tendrá el informe, es decir, los niveles con los que contará.",
      "fotos": ["164925535924"]
    },
    {
      "n": 6,
      "id": "contabilidad.configurar-informe-contable#6",
