{
  "intro": "Para configurar la emisión electrónica en el S10, debe registrar la resolución SUNAT en la empresa emisora, crear tipos de documentos, definir talonarios calificados y configurar números de serie y números específicos para cada tipo de documento.",
  "pasos": [
    {
      "n": 1,
      "id": "facturacion-electronica.configurar-emision-electronica#1",
      "texto": "En la ficha de datos de la empresa emisora, registre en el campo **N° Autorización Comprobante** el número de resolución que la SUNAT publicó y que la acredita como emisor electrónico.",
      "fotos": ["8d6196721b1f"]
    },
    {
      "n": 2,
      "id": "facturacion-electronica.configurar-emision-electronica#2",
      "texto": "Cree un tipo de documento para Boletas de Venta, Facturas, Notas de Crédito y Notas de Débito, para la calificación predeterminada de los documentos electrónicos.",
      "fotos": ["d103fcf2651d"]
    },
    {
      "n": 3,
      "id": "facturacion-electronica.configurar-emision-electronica#3",
      "texto": "Defina talonarios calificados para el **Sistema de Emisión Electrónica**.",
      "fotos": []
    },
    {
      "n": 4,
      "id": "facturacion-electronica.configurar-emision-electronica#4",
      "texto": "Registre el número de serie: debe iniciar con una letra y tener como máximo 4 caracteres; para las facturas y sus notas de crédito o débito, con la letra «F»; para las boletas y sus notas, con la letra «B».",
      "fotos": []
    },
    {
      "n": 5,
      "id": "facturacion-electronica.configurar-emision-electronica#5",
      "texto": "Configure el número: como máximo 8 dígitos, y debe empezar en 1.",
      "fotos": ["6bdce53ea17b"]
    },
    {
      "n": 6,
      "id": "facturacion-electronica.configurar-emision-electronica#6",
      "texto": "Dé acceso al talonario a los usuarios encargados de la emisión de documentos.",
      "fotos": ["439b86fa2d9e"]
    }
  ]
}

{
  "intro": "Para importar saldos por cobrar desde Excel, primero debe llenar un formato con los saldos pendientes y crear un recurso en el sistema.",
  "pasos": [
    {
      "n": 1,
      "id": "facturacion.importar-saldos-por-cobrar#1",
      "texto": "Llene el formato en Excel con los saldos pendientes por cobrar.",
      "fotos": ["d508833c4eb9"]
    },
    {
      "n": 2,
      "id": "facturacion.importar-saldos-por-cobrar#2",
      "texto": "Cree un recurso con el nombre 'RECURSO PARA LA IMPORTACIÓN DE SALDOS'.",
      "fotos": ["50de52fcd3db"]
    },
    {
      "n": 3,
      "id": "facturacion.importar-saldos-por-cobrar#3",
      "texto": "Ingresar al sistema como SA y ubicarse en el grupo Facturación, escenario Documentos por cobrar.",
      "fotos": []
    },
    {
      "n": 4,
      "id": "facturacion.importar-saldos-por-cobrar#4",
      "texto": "En la configuración de registros de documentos, elija el recurso 'RECURSO PARA LA IMPORTACIÓN DE SALDOS'.",
      "fotos": ["f6e453138085"]
    },
    {
      "n": 5,
      "id": "facturacion.importar-saldos-por-cobrar#5",
      "texto": "En el escenario Documentos por cobrar, haga clic derecho y seleccione la importación de saldos por cobrar.",
      "fotos": ["4ff0a14c966c"]
    },
    {
      "n": 6,
      "id": "facturacion.importar-saldos-por-cobrar#6",
      "texto": "Ingrese el año del periodo y haga clic en OK.",
      "fotos": ["ec6286b757b7"]
    }
  ]
}

{
