      "fotos": ["56e4e643c7a3"]
    },
    {
      "n": 3,
      "id": "instalacion.sacar-copia-de-seguridad-de-la-base-de-datos#3",
      "texto": "Haga clic en **Copia de seguridad de base de datos**.",
      "fotos": ["a205142cd367"]
    },
    {
      "n": 4,
      "id": "instalacion.sacar-copia-de-seguridad-de-la-base-de-datos#4",
